// Separate recurrence: forward-extension Hamilton DP on every literal child.
#define main producer_entry_point
#include "zero_escape.cpp"
#undef main
U forward_count(const std::vector<unsigned>&a){int n=a.size();unsigned N=1u<<n;std::vector<U>dp(size_t(N)*n);for(int i=0;i<n;i++)dp[(1u<<i)*n+i]=1;for(unsigned mask=1;mask<N;mask++){unsigned ends=mask;while(ends){int i=__builtin_ctz(ends);ends&=ends-1;U v=dp[size_t(mask)*n+i];if(!v)continue;unsigned next=a[i]&~mask;while(next){int j=__builtin_ctz(next);next&=next-1;dp[size_t(mask|(1u<<j))*n+j]+=v;}}}U h=0;for(int i=0;i<n;i++)h+=dp[size_t(N-1)*n+i];return h;}
int main(int argc,char**argv){try{ck(argc==3,"usage: direct_child_audit k quotient_code");int k=std::stoi(argv[1]);unsigned code=std::stoul(argv[2]);ck(3<=k&&k<=7,"audited arithmetic range");auto T=blow(decode(k,code));int m=T.size();std::vector<unsigned>B(m-1);for(int i=1;i<m;i++)for(int j=1;j<m;j++)if(T[i]>>j&1)B[i-1]|=1u<<(j-1);Field f=field(B);int n=B.size();U checks=0;U h=forward_count(B);ck(h==f.h,"direct parent H");auto literal=[&](unsigned S){auto a=B;for(int i=0;i<n;i++)if(!(S>>i&1))a[i]|=1u<<n;a.push_back(S);U v=forward_count(a);ck(I(v)==value(f,S),"direct child versus exposure polynomial");checks++;return v;};U h0=literal(0);ck(h0==h,"source/sink neutrality");std::vector<U>single(n);for(int i=0;i<n;i++){single[i]=literal(1u<<i);ck(I(single[i]-h)==f.A[i],"singleton coefficient");}for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){U both=literal((1u<<i)|(1u<<j));ck(I(single[i]+single[j]-h-both)==f.C[i*n+j],"pair curvature coefficient");}unsigned old=0;for(int j=1;j<m;j++)if(T[0]>>j&1)old|=1u<<(j-1);U ht=literal(old);ck(ht==forward_count(T),"original child explicit reordered T");std::cout<<"PASS k "<<k<<" quotient "<<code<<" parent_order "<<n<<" parent_H "<<h<<" child_H "<<ht<<" literal_child_checks "<<checks<<" full_coefficients "<<(1+n+n*(n-1)/2)<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
